param([string]$InstallRoot="C:\AndysBot\agentic-r7.6-execution-quality",[string]$RepoZip="https://github.com/chipblock2/andys-bot-updates/archive/refs/heads/main.zip")
$ErrorActionPreference="Stop";$work=Join-Path $env:TEMP ("andys-r76-"+[guid]::NewGuid().ToString("N"));$zip="$work.zip"
try{Invoke-WebRequest -UseBasicParsing -Uri $RepoZip -OutFile $zip;Expand-Archive -Path $zip -DestinationPath $work -Force;$src=Get-ChildItem $work -Directory|Select-Object -First 1;$src=Join-Path $src.FullName "agentic-r7.6-execution-quality";if(!(Test-Path (Join-Path $src "self_test.py"))){throw "R7.6 source not found"};New-Item -ItemType Directory -Force -Path $InstallRoot|Out-Null;Copy-Item "$src\*" $InstallRoot -Recurse -Force;Push-Location $InstallRoot;try{python -m py_compile *.py;python self_test.py;python self_test_extended.py}finally{Pop-Location};Write-Host "R7.6 SHADOW INSTALL VERIFIED: $InstallRoot"}finally{Remove-Item $zip -Force -ErrorAction SilentlyContinue;Remove-Item $work -Recurse -Force -ErrorAction SilentlyContinue}